"""Webhook request handling for Linkweave billing events."""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from typing import Any

import event_store
from event_store import append_event
from signature_utils import verify_signature


REQUIRED_EVENT_FIELDS = ("event_id", "event_type", "account_id")

_IMPORT_TIME_APPEND_EVENT = append_event


def handle_health_ping(request: Mapping[str, Any]) -> dict[str, Any]:
    """Existing endpoint used by the health monitor."""

    body = request.get("body", b"")
    headers = request.get("headers", {})
    secret = os.environ.get("WEBHOOK_SECRET", "")
    if not isinstance(body, bytes) or not isinstance(headers, Mapping):
        return {"status": "rejected", "reason": "malformed request"}
    if not verify_signature(body, headers.get("X-Webhook-Signature"), secret):
        return {"status": "rejected", "reason": "invalid signature"}
    return {"status": "ok"}


def _parse_event(body: bytes) -> dict[str, Any] | None:
    """Return the payload only when the body is a well-formed payment event."""

    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return None
    if not isinstance(payload, dict):
        return None
    for field in REQUIRED_EVENT_FIELDS:
        value = payload.get(field)
        if not isinstance(value, str) or not value:
            return None
    return payload


def _append_event(event: dict[str, Any]) -> None:
    """Queue one event through the active `event_store.append_event` binding."""

    if append_event is _IMPORT_TIME_APPEND_EVENT:
        event_store.append_event(event)
    else:
        append_event(event)


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event."""

    if not isinstance(request, Mapping):
        return {"status": "rejected", "reason": "malformed request"}

    body = request.get("body", b"")
    headers = request.get("headers", {})
    secret = os.environ.get("WEBHOOK_SECRET", "")
    if not isinstance(body, bytes) or not isinstance(headers, Mapping):
        return {"status": "rejected", "reason": "malformed request"}
    if not secret:
        return {"status": "rejected", "reason": "missing secret"}
    if not verify_signature(body, headers.get("X-Webhook-Signature"), secret):
        return {"status": "rejected", "reason": "invalid signature"}

    event = _parse_event(body)
    if event is None:
        return {"status": "rejected", "reason": "invalid event payload"}

    _append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}
